export function Draft({
  title = "{{title}}",
  excerpt = "{{excerpt}}",
  lastEdited = "{{lastEdited}}",
  visibility = "{{visibility}}",
  accent = "{{accent}}",
}) {
  const icon = visibility === "unlisted" ? "\uD83D\uDD17" : "\uD83D\uDD12";
  return (
    <article style={{ fontFamily: "system-ui, sans-serif", fontSize: 15, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", border: "1.5px dashed #24143040", borderRadius: 12, padding: "16px 18px", maxWidth: 340 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <span style={{ fontWeight: 700, fontSize: 11, letterSpacing: ".04em", textTransform: "uppercase",
          color: "#241430", background: accent, padding: "3px 8px", borderRadius: 999 }}>Draft</span>
        <span style={{ fontSize: 12, color: "#24143099", textTransform: "capitalize" }}>{icon} {visibility}</span>
      </div>
      <h3 style={{ margin: "0 0 6px", fontSize: 17, fontWeight: 700 }}>{title}</h3>
      <p style={{ margin: "0 0 10px", color: "#241430cc" }}>{excerpt}</p>
      <p style={{ margin: 0, fontSize: 12, color: "#24143080" }}>{lastEdited}</p>
    </article>
  );
}
